package data_structures.class_problems;
import java.util.*;
public class Q3_LibraryReturnDesk {public static void main(String[] a){Scanner s=new Scanner(System.in);String[] stack=new String[3],queue=new String[3];int top=-1,front=0,rear=0,size=0,n=s.nextInt();for(int i=0;i<n;i++){String op=s.next(),v="";if(op.equals("RETURN")||op.equals("WAIT"))v=s.next();switch(op){case "RETURN":if(top==2)System.out.println(v+" rejected: pile is full");else{stack[++top]=v;System.out.println(v+" placed on pile");}break;case "SHELVE":if(top==-1)System.out.println("pile is empty");else System.out.println("shelved "+stack[top--]);break;case "WAIT":if(size==3)System.out.println(v+" rejected: line is full");else{queue[rear]=v;rear=(rear+1)%3;size++;System.out.println(v+" joined the line");}break;case "SERVE":if(size==0)System.out.println("no one waiting");else{System.out.println("served "+queue[front]);front=(front+1)%3;size--;}break;}}}}